/**
 * Pipedrive Node - Version 2
 * Discriminator: resource=lead, operation=get
 */


interface Credentials {
  pipedriveApi: CredentialReference;
  pipedriveOAuth2Api: CredentialReference;
}

/** Get an activity */
export type PipedriveV2LeadGetParams = {
  resource: 'lead';
  operation: 'get';
  authentication?: 'apiToken' | 'oAuth2' | Expression<string>;
/**
 * ID of the lead to retrieve
 */
    leadId: string | Expression<string>;
};

export type PipedriveV2LeadGetOutput = {
  add_time?: string;
  archive_time?: unknown;
  cc_email?: string;
  channel?: unknown;
  channel_id?: unknown;
  creator_id?: number;
  expected_close_date?: unknown;
  id?: string;
  is_archived?: boolean;
  label_ids?: Array<unknown>;
  next_activity_id?: unknown;
  organization_id?: number;
  origin?: string;
  origin_id?: unknown;
  owner_id?: number;
  person_id?: number;
  source_deal_id?: unknown;
  source_name?: string;
  title?: string;
  update_time?: string;
  value?: unknown;
  visible_to?: string;
  was_seen?: boolean;
};

export type PipedriveV2LeadGetNode = {
  type: 'n8n-nodes-base.pipedrive';
  version: 2;
  config: NodeConfig<PipedriveV2LeadGetParams> & { credentials?: Credentials };
  output?: Items<PipedriveV2LeadGetOutput>;
};